CREATE TABLE IF NOT EXISTS manual_payments (id INTEGER PRIMARY KEY AUTOINCREMENT, reference_code VARCHAR(100) UNIQUE NOT NULL, user_id INTEGER NOT NULL, booking_id INTEGER, payment_account_id INTEGER, payment_method VARCHAR(50) NOT NULL, amount DECIMAL(10,2) NOT NULL, sender_name VARCHAR(255), sender_bank VARCHAR(255), transaction_number VARCHAR(100), transfer_date DATE, status VARCHAR(50) DEFAULT 'pending_verification', notes TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, verified_at TIMESTAMP NULL, verified_by INTEGER NULL);
